public IEnumerable<string> FormatOrders(IEnumerable<Order> orders)
{
    var results = new List<string>();
    foreach (var order in orders)
    {
        // String interpolation allocates a new string each iteration.
        results.Add($"{order.Id}: {order.Total:C}");
    }
    return results;
}

private readonly StringBuilder _sb = new StringBuilder();

public string FormatOrder(Order order)
{
    _sb.Clear();
    _sb.Append(order.Id).Append(": ").Append(order.Total);
    return _sb.ToString();
}

// Or use ArrayPool for reusable buffers
public void Process(byte[] payload)
{
    var buffer = ArrayPool<byte>.Shared.Rent(payload.Length);
    try
    {
        Buffer.BlockCopy(payload, 0, buffer, 0, payload.Length);
        // work with buffer
    }
    finally
    {
        ArrayPool<byte>.Shared.Return(buffer);
    }
}
